import ee, math, sys
ee.Initialize(project='earthsense-436113')

def get_alabama_geometry():
    states = ee.FeatureCollection('TIGER/2018/States')
    ala = states.filter(ee.Filter.eq('NAME', 'Alabama')).first()
    return ee.Feature(ala).geometry()

def fetch_grace_collection(start, end):
    return ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND').filterDate(start, end)

def pick_band(img):
    # Prefer 'lwe_thickness' if present; otherwise fallback to the first band.
    names = img.bandNames()
    preferred = names.filter(ee.Filter.stringContains('item', 'lwe_thickness'))
    return ee.Algorithms.If(preferred.size().gt(0), preferred.get(0), names.get(0))

def year_stats(year, geom):
    start = ee.Date.fromYMD(year,1,1)
    end = start.advance(1, 'year')
    col = fetch_grace_collection(start, end)
    size = col.size().getInfo()
    if size == 0:
        # Fallback: expand window by +/- 1 month to tolerate edge inclusivity
        col = fetch_grace_collection(start.advance(-1,'month'), end.advance(1,'month'))
        size = col.size().getInfo()
        if size == 0:
            print(f"{year} Images: 0")
            return {'status':'C1'}
    first = ee.Image(col.first())
    try:
        band = ee.String(pick_band(first)).getInfo()
    except Exception as e:
        print(f"{year} Band detection error: {e}")
        return {'status':'D'}
    mean_img = col.select([band]).mean()
    # Count valid pixels over Alabama at mascon scale (~100 km)
    count = mean_img.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=100000,
        maxPixels=1e9,
        tileScale=2
    ).get(band).getInfo()
    if (count is None) or (int(count) == 0):
        print(f"{year} Images: {size}, Pixels: 0")
        return {'status':'C2'}
    val = mean_img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom,
        scale=100000,
        maxPixels=1e9,
        tileScale=2
    ).get(band).getInfo()
    if (val is None) or (not isinstance(val, (int,float))) or (not math.isfinite(val)) or (abs(val) > 1000):
        print(f"{year} Images: {size}, Mean(cm): {val}, Pixels: {int(count)}")
        return {'status':'C3'}
    print(f"{year} Images: {size}, Mean(cm): {val:.2f}, Pixels: {int(count)}")
    return {'status':'OK', 'mean': float(val), 'count': int(count), 'size': int(size)}

def main():
    try:
        geom = get_alabama_geometry()
    except Exception as e:
        print(f"Geometry error: {e}")
        print("D")
        return

    s2003 = year_stats(2003, geom)
    if s2003['status'] != 'OK':
        print(s2003['status'])
        return

    s2012 = year_stats(2012, geom)
    if s2012['status'] != 'OK':
        print(s2012['status'])
        return

    diff = s2012['mean'] - s2003['mean']
    print(f"Diff 2012-2003 (cm): {diff:.2f}")
    # Final decision: decrease if 2012 < 2003
    print("A" if s2012['mean'] < s2003['mean'] else "B")

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        # Catch-all for unexpected API or memory issues
        msg = str(e)
        # keep output concise
        print(f"Error: {msg[:200]}")
        print("D")
